import { Command } from 'commander';
import ora from 'ora';
import { git } from '../utils/git.js';
import { reviewDiff } from '../ai/codeReview.js';

export function registerReview(program: Command) {
  program
    .command('review')
    .description('AI code review of staged changes')
    .action(async () => {
      const spinner = ora('Analyzing staged changes...').start();
      const diff = await git().diff(['--cached']);
      if (!diff.trim()) {
        spinner.fail('No staged changes to review.');
        return;
      }
      const feedback = await reviewDiff(diff);
      spinner.stop();
      console.log('\nAI Review Suggestions:\n', feedback);
    });
}
